 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The full-width stripe separates the object from its destination.
    stripe = next(r for r, row in enumerate(grid)
                 if len(set(row)) == 1 and row[0] != max(set(v for x in grid for v in x), key=lambda v: sum(x.count(v) for x in grid)))
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    obj_colors = {v for r, row in enumerate(grid) if r != stripe for v in row if v != bg}
    obj_color = next(iter(obj_colors))
    cells = [(r, c) for r in range(h) if r != stripe for c in range(w) if grid[r][c] == obj_color]
    minr, maxr = min(r for r, c in cells), max(r for r, c in cells)
    if maxr < stripe:
        shift = stripe - 1 - maxr
        edge = minr + shift - 1
    else:
        shift = stripe + 1 - minr
        edge = maxr + shift + 1
    # Clear the original object, move it flush against the stripe, then mark
    # the vacated-side boundary with color 8.
    for r, c in cells:
        out[r][c] = bg
    for r, c in cells:
        out[r + shift][c] = grid[r][c]
    if 0 <= edge < h:
        out[edge] = [8] * w
    return out
